<script setup lang="ts">
import { computed } from 'vue'
import { Head, Link, useForm } from '@inertiajs/vue3'
import { appUrl } from '@/lib/url'
import { ArrowLeft, FileText, ReceiptText } from 'lucide-vue-next'
import ClinicLayout from '@/Layouts/ClinicLayout.vue'

interface Item { id: string; tooth_number: number | null; surface: string; quantity: number; clinical_note: string | null; priority: string; estimated_minutes: number | null; status: string; procedure: { code: string | null; name: string }; quote_items: { quote: { id: string; quote_number: string } }[] }
interface Plan { id: string; title: string; status: string; notes: string | null; patient: { id: string; full_name: string; record_number: string }; encounter: { id: string }; diagnosis: { code: string | null; description: string } | null; items: Item[] }
const props = defineProps<{ plan: Plan }>()
const form = useForm({ alternative_name: `Cotización: ${props.plan.title}`, item_ids: props.plan.items.filter(item => ['proposed', 'deferred'].includes(item.status)).map(item => item.id) })
const quotableItems = computed(() => props.plan.items.filter(item => ['proposed', 'deferred'].includes(item.status)))
function submit() { form.post(appUrl(`/clinical-plans/${props.plan.id}/quotes`)) }
</script>

<template>
    <Head :title="plan.title" />
    <ClinicLayout><div class="mx-auto max-w-6xl space-y-5"><header class="flex flex-col justify-between gap-3 border-b border-[#D8E0DE] pb-5 md:flex-row md:items-end"><div><p class="text-xs font-bold uppercase tracking-[0.16em] text-[#006B63]">Plan clínico · {{ plan.status }}</p><h1 class="mt-1 text-2xl font-bold text-[#131B2E]">{{ plan.title }}</h1><p class="mt-1 text-sm text-[#667085]">{{ plan.patient.full_name }} · {{ plan.patient.record_number }}<span v-if="plan.diagnosis"> · {{ plan.diagnosis.code || 'S/C' }} {{ plan.diagnosis.description }}</span></p></div><Link :href="appUrl(`/encounters/${plan.encounter.id}`)" class="inline-flex h-10 items-center gap-2 border border-[#9AAEAA] bg-white px-4 text-sm font-semibold text-[#005C55]"><ArrowLeft class="h-4 w-4" /> Encuentro</Link></header><section class="border border-[#D8E0DE] bg-white p-5"><h2 class="flex items-center gap-2 font-bold text-[#131B2E]"><FileText class="h-5 w-5 text-[#006B63]" /> Razonamiento clínico</h2><p class="mt-3 whitespace-pre-line text-sm text-[#455653]">{{ plan.notes || 'Sin nota general.' }}</p></section><form class="grid gap-5 xl:grid-cols-[1fr_320px]" @submit.prevent="submit"><section class="overflow-hidden border border-[#BDC9C6] bg-white"><table class="w-full text-left text-sm"><thead class="bg-[#F2F6F5] text-xs uppercase text-[#455653]"><tr><th class="p-3">Cotizar</th><th class="p-3">Procedimiento</th><th class="p-3">Contexto</th><th class="p-3">Estado</th></tr></thead><tbody><tr v-for="item in plan.items" :key="item.id" class="border-t border-[#E2E8F0]"><td class="p-3"><input v-if="['proposed', 'deferred'].includes(item.status)" v-model="form.item_ids" type="checkbox" :value="item.id" /></td><td class="p-3"><p class="font-semibold text-[#131B2E]">{{ item.procedure.name }}</p><p class="font-mono text-xs text-[#667085]">{{ item.procedure.code || 'S/C' }} · {{ item.quantity }}x · {{ item.tooth_number || 'General' }}</p></td><td class="p-3"><p>{{ item.priority }} · {{ item.estimated_minutes || '—' }} min</p><p class="mt-1 text-xs text-[#667085]">{{ item.clinical_note || 'Sin justificación adicional' }}</p></td><td class="p-3"><span class="font-semibold text-[#006B63]">{{ item.status }}</span><Link v-for="quoteItem in item.quote_items" :key="quoteItem.quote.id" :href="appUrl(`/quotes/${quoteItem.quote.id}`)" class="mt-1 block text-xs text-[#006B63]">{{ quoteItem.quote.quote_number }}</Link></td></tr></tbody></table></section><aside class="h-fit border border-[#BDC9C6] bg-white p-5 xl:sticky xl:top-24"><ReceiptText class="h-6 w-6 text-[#006B63]" /><h2 class="mt-3 font-bold text-[#131B2E]">Generar cotización</h2><p class="mt-2 text-sm text-[#667085]">Los precios e impuestos se fijan ahora desde el catálogo. La aprobación de esa cotización crea el tratamiento ejecutable.</p><label class="mt-4 block text-xs font-bold text-[#455653]">Nombre<input v-model="form.alternative_name" required maxlength="255" class="mt-1 h-10 w-full border border-[#9AAEAA] px-3 text-sm font-normal" /></label><button :disabled="form.processing || !form.item_ids.length" class="mt-4 h-11 w-full bg-[#005C55] text-sm font-semibold text-white disabled:opacity-50">Cotizar seleccionados ({{ form.item_ids.length }}/{{ quotableItems.length }})</button></aside></form></div></ClinicLayout>
</template>
